export interface MovieRecapData {
  title: string;
  originalTitle: string;
  year: string;
  genre: string[];
  director: string;
  duration: string;
  imdbRating: string;
  tagline: string;
  logline: string;
  overview: string;
  characters: Array<{
    name: string;
    actor?: string;
    role: string;
    description: string;
    fate?: string;
  }>;
  scenes: Array<{
    timestamp: string;
    title: string;
    description: string;
    intensity: string;
    mood: string;
  }>;
  twistEnding: {
    hasMajorTwist: boolean;
    twistSummary: string;
    endingExplanation: string;
    hiddenClues: string[];
  };
  voiceoverScript: {
    hook: string;
    fullScript: string;
    estimatedNarrationTime: string;
    toneRecommendation: string;
  };
  moralAndThemes: string[];
  creatorPack: {
    suggestedVideoTitle: string;
    thumbnailConcept: string;
    hashtags: string[];
    retentionTip?: string;
  };
}

