// Genre-specific procedural templates for any other movie or uploaded video
interface GenreArchetype {
  genreName: string;
  burmeseGenre: string;
  protagonistRole: string;
  antagonistRole: string;
  supportingRole: string;
  loglineTemplate: (title: string) => string;
  overviewTemplate: (title: string, tone: string) => string;
  sceneTemplates: (title: string) => Array<{
    timestamp: string;
    title: string;
    description: string;
    intensity: string;
    mood: string;
  }>;
  twistTemplate: (title: string) => {
    twistSummary: string;
    endingExplanation: string;
    hiddenClues: string[];
  };
  scriptTemplate: (title: string, tone: string) => {
    hook: string;
    fullScript: string;
    estimatedNarrationTime: string;
    toneRecommendation: string;
  };
}

